list_shipping_profiles.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.shippingProfiles().listShippingProfiles(Map.of("search", "metro", "sort", "name", "order", "asc", "limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("shipping_profiles")) {
    Map<?, ?> profile = (Map<?, ?>) row;
    System.out.println(profile.get("id") + " " + profile.get("name") + " " + profile.get("rule_preference") + " " + profile.get("default"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

